"""Opt-in enrichment of the application's existing GenAI producers.

configure never owns SDK shutdown, creates no exporter, and changes no global
provider. AgentDemo's supported hooks are the only operation integration points.
"""

from contextlib import contextmanager
from contextvars import ContextVar
import json
from pathlib import Path
import re

from jsonschema import Draft202012Validator, ValidationError
from opentelemetry import trace
from opentelemetry.trace import SpanKind, Status, StatusCode

from bootstrap import load_binding

MAX_MESSAGES = 16
MAX_PARTS = 64
MAX_BYTES = 8192
MAX_TEXT_BYTES = 1024
MAX_DEPTH = 12
SCHEMAS = json.loads(Path(__file__).with_name("genai_schemas.json").read_text())
VALIDATORS = {name: Draft202012Validator(schema) for name, schema in SCHEMAS.items()}
SENSITIVE = re.compile(
    r"(?i)(password|secret|token|authorization|api[_-]?key|email|"
    r"user[_-]?id|customer[_-]?id|tenant[_-]?id|account[_-]?id|"
    r"session[_-]?id|reasoning|chain[_ -]?of[_ -]?thought|analysis)"
)
LABELLED = re.compile(
    r"(?i)\b(password|secret|token|authorization|api[_-]?key|email|"
    r"user[_-]?id|customer[_-]?id|tenant[_-]?id|account[_-]?id|"
    r"session[_-]?id|reasoning|chain[_ -]?of[_ -]?thought|analysis)"
    r"[\"']?\s*[:=]\s*(?:\"[^\"]*\"|'[^']*'|[^,;\n]+)"
)


def sanitize(value, depth=0):
    """Transform a copy before any span setter; business values stay untouched."""
    if depth > MAX_DEPTH:
        return "[truncated]"
    if isinstance(value, dict):
        return {str(k)[:128]: sanitize(v, depth + 1) for k, v in list(value.items())[:64]
                if not SENSITIVE.search(str(k))}
    if isinstance(value, (list, tuple)):
        return [sanitize(v, depth + 1) for v in value[:64]
                if not isinstance(v, dict) or v.get("type") != "reasoning"]
    if isinstance(value, str):
        # Embedded JSON must receive the same policy as structured arguments.
        try:
            parsed = json.loads(value)
        except (ValueError, RecursionError):
            parsed = None
        if isinstance(parsed, (dict, list)):
            return json.dumps(sanitize(parsed, depth + 1), ensure_ascii=False)
        value = re.sub(r"private-prompt-sentinel", "[redacted]", value)
        value = re.sub(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}", "[redacted]", value)
        value = re.sub(r"(?i)\bBearer\s+\S+", "[redacted]", value)
        value = re.sub(r"\b(?:sk-|sk_)[A-Za-z0-9_-]+", "[redacted]", value)
        value = LABELLED.sub(lambda match: match[1] + "=[redacted]", value)
        return value.encode("utf-8")[:MAX_TEXT_BYTES].decode("utf-8", errors="ignore")
    if value is None or isinstance(value, (bool, int, float)):
        return value
    return "[unsupported]"


def validate_messages(messages, output=False):
    """Validate the full schema AND each recognized concrete part.

    The schema's permissive GenericPart must not accept a malformed known part.
    Unknown extension types remain governed by the complete published schema.
    """
    name = "gen-ai-output-messages.json" if output else "gen-ai-input-messages.json"
    schema = SCHEMAS[name]
    VALIDATORS[name].validate(messages)
    if len(messages) > MAX_MESSAGES:
        raise ValueError("message_count")
    concrete = {definition["properties"]["type"]["const"]: key
                for key, definition in schema["$defs"].items()
                if "const" in definition.get("properties", {}).get("type", {})}
    for message in messages:
        if len(message["parts"]) > MAX_PARTS:
            raise ValueError("part_count")
        for part in message["parts"]:
            if part["type"] in concrete:
                Draft202012Validator({"$defs": schema["$defs"],
                                      "$ref": "#/$defs/" + concrete[part["type"]]}).validate(part)
    if len(json.dumps(messages, ensure_ascii=False).encode("utf-8")) > MAX_BYTES:
        raise ValueError("message_bytes")


def capture(span, attribute, value, *, output=False):
    original = value
    if attribute.endswith(".messages"):
        value = [{**message, "parts": message["parts"][:MAX_PARTS]}
                 for message in value[:MAX_MESSAGES]]
    safe = sanitize(value)
    try:
        if attribute.endswith(".messages"):
            validate_messages(safe, output)
        else:
            schema_name = {"gen_ai.tool.call.arguments": "gen-ai-tool-call-arguments.json",
                           "gen_ai.tool.call.result": "gen-ai-tool-call-result.json"}.get(attribute)
            if schema_name:
                VALIDATORS[schema_name].validate(safe)
        encoded = json.dumps(safe, ensure_ascii=False, allow_nan=False)
        if len(encoded.encode("utf-8")) > MAX_BYTES:
            raise ValueError("content_bytes")
    except (ValueError, TypeError, ValidationError):
        span.set_attribute("app.content.omitted", True)
        return
    if safe != original:
        span.set_attribute("app.content.transformed", True)
    span.set_attribute(attribute, encoded)


def text_messages(value, role):
    return [{"role": role, "parts": [{"type": "text", "content":
             value if isinstance(value, str) else json.dumps(value, ensure_ascii=False)}]}]


def configure(app):
    """Register once per app; the actual probe intentionally calls this twice."""
    if app.mode != "genai" or getattr(app, "_genai_instrumentation", None) is not None:
        return
    if app.trace_provider is None or app.trace_producer is None:
        raise ValueError("genai_trace_owner_missing")
    binding = load_binding(app)
    tracer = app.trace_provider.get_tracer("support.operations", "1.0")
    owning_agent = ContextVar("support_owning_agent", default=None)
    names = {"agent": "invoke_agent support_agent", "retrieval": "retrieval knowledge_base",
             "tool": "execute_tool lookup_order"}
    operations = {"workflow": "invoke_workflow", "agent": "invoke_agent", "retrieval": "retrieval",
                  "tool": "execute_tool", "model": "chat"}

    def enrich(span, operation, state):
        if operation == "workflow" and binding is not None:
            binding.refresh()
        span.set_attribute("gen_ai.operation.name", operations[operation])
        span.set_attribute("app.request_id", state["request_id"])
        span.set_attribute("app.scenario", state["scenario"])
        span.set_attribute("app.content.capture_mode", "redacted")
        if operation == "workflow":
            span.set_attribute("gen_ai.workflow.name", "support_turn")
        elif operation == "agent":
            span.set_attribute("gen_ai.agent.name", state["agent_name"])
            span.set_attribute("gen_ai.request.model", "demo-model")
        elif operation == "model":
            span.set_attribute("gen_ai.request.model", state["model"])
        elif operation == "retrieval":
            span.set_attribute("gen_ai.data_source.id", state["data_source"])
        elif operation == "tool":
            span.set_attribute("gen_ai.tool.name", state["tool_name"])
            span.set_attribute("gen_ai.tool.type", "function")
            if owning_agent.get() is not None:
                span.set_attribute("gen_ai.agent.name", owning_agent.get())
        if binding is not None:
            binding.annotate(span)

    def content(span, operation, state, output=False):
        if output and not state.get("result_available"):
            return
        value = state["result"] if output else state["inputs"]
        if operation == "retrieval":
            if output:
                capture(span, "gen_ai.retrieval.documents", [{"content": d} for d in value])
            else:
                span.set_attribute("gen_ai.retrieval.query.text", sanitize(value["query"]))
            return
        attribute = "gen_ai.output.messages" if output else "gen_ai.input.messages"
        if operation == "tool":
            # The supplied call-result schema is an object. Preserve a genuine
            # scalar/null result in a named field, and its exact typed response
            # in output.messages; failure never reaches this branch.
            result_value = {"result": value} if output and not isinstance(value, dict) else value
            capture(span, "gen_ai.tool.call.result" if output else "gen_ai.tool.call.arguments", result_value)
            # No model-generated call ID exists in this source. Preserve typed
            # operation content without inventing a model/tool feedback turn.
            part = ({"type": "tool_call_response", "response": value} if output else
                    {"type": "tool_call", "name": state["tool_name"], "arguments": value})
            messages = [{"role": "tool" if output else "assistant", "parts": [part]}]
        else:
            messages = text_messages(value, "assistant" if output else "user")
        capture(span, attribute, messages, output=output)

    @contextmanager
    def operation_hook(operation, state):
        if operation not in operations or (operation == "tool" and state.get("tool_name") != "lookup_order"):
            yield
            return
        existing = operation in ("workflow", "model")
        if existing:
            span = trace.get_current_span()
            manager = trace.use_span(span, end_on_exit=False, record_exception=False,
                                     set_status_on_exception=False)
        else:
            manager = tracer.start_as_current_span(names[operation], kind=SpanKind.INTERNAL,
                                                   record_exception=False, set_status_on_exception=False)
        with manager as span:
            if not existing:
                enrich(span, operation, state)
            content(span, operation, state)
            agent_token = owning_agent.set(state["agent_name"]) if operation == "agent" else None
            try:
                yield
            except BaseException as error:
                span.set_attribute("error.type", type(error).__name__)
                # Existing producer already records ordinary Exception errors.
                # It does not catch cancellation (BaseException).
                if not existing or not isinstance(error, Exception):
                    span.set_status(Status(StatusCode.ERROR))
                    span.add_event("exception", {"exception.type": type(error).__name__,
                                                 "exception.message": "operation failed"})
                raise
            else:
                content(span, operation, state, output=True)
            finally:
                if agent_token is not None:
                    owning_agent.reset(agent_token)

    app.trace_producer.span_hooks.append(enrich)
    app.operation_hooks.append(operation_hook)
    app._genai_instrumentation = {"binding": binding, "tracer": tracer}

"""Incremental native OTel tracing for the application's logs-only profile.

No global provider, log bridge, business wrapper, or exporter replacement.
"""
from __future__ import annotations

import contextlib
import json
import os
import re
from pathlib import Path
from uuid import UUID

from jsonschema import Draft202012Validator
from opentelemetry import trace
from opentelemetry.trace import SpanKind, Status, StatusCode
from opentelemetry.sdk.resources import Resource
from opentelemetry.sdk.trace import TracerProvider, ReadableSpan
from opentelemetry.sdk.trace.export import BatchSpanProcessor
from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter

from app import RESOURCE
from resource_resolution import (
    StudioAPI, StudioProjects, StudioAgentStreams, resolve_resources,
    native_trace_binding, ResolutionError,
)

MAX_MESSAGES, MAX_PARTS, MAX_BYTES = 16, 64, 8192
_SCHEMAS = json.loads(Path(__file__).with_name("genai_schemas.json").read_text())["schemas"]
_PRIVATE = re.compile(
    r"(?i)(?:password|secret|token|authorization|api[_ -]?key|email|"
    r"user[_ -]?id|tenant[_ -]?id|session[_ -]?id|order[_ -]?id|"
    r"chain[_ -]?of[_ -]?thought|reasoning|private[_ -]?prompt)"
)
_LABEL = re.compile(
    r'(?i)\b(password|secret|token|authorization|api[_ -]?key|email|user[_ -]?id|'
    r'tenant[_ -]?id|session[_ -]?id|order[_ -]?id|chain[_ -]?of[_ -]?thought|reasoning)'
    r'\s*[:=]\s*(?:"[^"]*"|\x27[^\x27]*\x27|[^,;\n]+)'
)
_EMAIL = re.compile(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}")
_NAMES = {
    "workflow": ("invoke_workflow support_turn", "invoke_workflow", SpanKind.INTERNAL),
    "agent": ("invoke_agent support_agent", "invoke_agent", SpanKind.INTERNAL),
    "retrieval": ("retrieval knowledge_base", "retrieval", SpanKind.INTERNAL),
    "tool": ("execute_tool lookup_order", "execute_tool", SpanKind.INTERNAL),
    "model": ("chat demo-model", "chat", SpanKind.CLIENT),
}


def sanitize(value, depth=0):
    """Transform a copy before any SDK setter; never mutate business values."""
    if depth > 12:
        return "[depth limit]"
    if isinstance(value, dict):
        if value.get("type") == "reasoning":
            return {"type": "reasoning", "content": "[redacted]"}
        return {str(k): "[redacted]" if _PRIVATE.search(str(k)) else sanitize(v, depth + 1)
                for k, v in list(value.items())[:64]}
    if isinstance(value, (list, tuple)):
        return [sanitize(v, depth + 1) for v in value[:64]]
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except (ValueError, TypeError):
            text = value.replace("private-prompt-sentinel", "[redacted]")
            text = _EMAIL.sub("[redacted]", _LABEL.sub(lambda m: m[1] + "=[redacted]", text))
            return text.encode("utf-8")[:MAX_BYTES // 4].decode("utf-8", "ignore")
        else:
            # JSON embedded in text must receive the same nested policy.
            if isinstance(parsed, (dict, list)):
                return json.dumps(sanitize(parsed, depth + 1), ensure_ascii=False)
            return value.encode("utf-8")[:MAX_BYTES // 4].decode("utf-8", "ignore")
    if value is None or isinstance(value, (bool, int, float)):
        return value
    return "[unsupported]"


def _truncated(value, depth=0):
    if depth > 12:
        return True
    if isinstance(value, str):
        return len(value.encode("utf-8")) > MAX_BYTES // 4
    if isinstance(value, dict):
        return len(value) > 64 or any(_truncated(v, depth + 1) for v in list(value.values())[:64])
    if isinstance(value, (list, tuple)):
        return len(value) > 64 or any(_truncated(v, depth + 1) for v in value[:64])
    return False


def validate_messages(messages, output=False):
    """Validate the whole schema AND each known part, defeating GenericPart fallback."""
    schema = _SCHEMAS[f"model/gen-ai/gen-ai-{'output' if output else 'input'}-messages.json"]
    Draft202012Validator(schema).validate(messages)
    if len(messages) > MAX_MESSAGES:
        raise ValueError("message_limit")
    for message in messages:
        if len(message["parts"]) > MAX_PARTS:
            raise ValueError("part_limit")
        for part in message["parts"]:
            for name, definition in schema["$defs"].items():
                if definition.get("properties", {}).get("type", {}).get("const") == part["type"]:
                    Draft202012Validator({"$defs": schema["$defs"], "$ref": f"#/$defs/{name}"}).validate(part)
    if len(json.dumps(messages, ensure_ascii=False).encode("utf-8")) > MAX_BYTES:
        raise ValueError("content_limit")
    return messages


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False)


def _set_json(span, key, value):
    encoded = _json(value)
    if len(encoded.encode("utf-8")) <= MAX_BYTES:
        span.set_attribute(key, encoded)
    else:
        span.set_attribute("app.capture.truncated", True)


def _message(span, key, value, *, output=False, part=None, role=None):
    safe = sanitize(value)
    parts = [part(safe)] if part else [{"type": "text", "content": safe if isinstance(safe, str) else _json(safe)}]
    message = {"role": role or ("assistant" if output else "user"), "parts": parts}
    messages = [message]
    try:
        validate_messages(messages, output)
    except ValueError:
        span.set_attribute("app.capture.truncated", True)
        return
    _set_json(span, key, messages)


def validate_tool_content(attributes, result_available):
    """Tool message mappings must agree with the actual sanitized boundary fields."""
    inputs = json.loads(attributes["gen_ai.input.messages"])
    validate_messages(inputs)
    assert len(inputs) == 1 and len(inputs[0]["parts"]) == 1
    part = inputs[0]["parts"][0]
    assert part["type"] == "tool_call"
    assert part["name"] == attributes["gen_ai.tool.name"]
    assert part["arguments"] == json.loads(attributes["gen_ai.tool.call.arguments"])
    if result_available:
        outputs = json.loads(attributes["gen_ai.output.messages"])
        validate_messages(outputs, output=True)
        assert len(outputs) == 1 and len(outputs[0]["parts"]) == 1
        part = outputs[0]["parts"][0]
        assert part["type"] == "tool_call_response"
        assert part["response"] == json.loads(attributes["gen_ai.tool.call.result"])
    else:
        assert "gen_ai.output.messages" not in attributes
        assert "gen_ai.tool.call.result" not in attributes


def _enrich(span, operation, state, *, finished=False):
    _, semantic, _ = _NAMES[operation]
    span.set_attribute("gen_ai.operation.name", semantic)
    span.set_attribute("app.request_id", state["request_id"])
    span.set_attribute("app.scenario", state["scenario"])
    span.set_attribute("app.capture.mode", "redacted")
    if operation == "workflow":
        span.set_attribute("gen_ai.workflow.name", "support_turn")
    if operation in {"agent", "tool"}:
        span.set_attribute("gen_ai.agent.name", "support_agent")
    if operation in {"agent", "model"}:
        span.set_attribute("gen_ai.request.model", "demo-model")
    # Provider identity/usage/IDs are absent from source; do not infer them.
    if _truncated(state.get("inputs", {})) or (finished and _truncated(state.get("result"))):
        span.set_attribute("app.capture.truncated", True)
    inputs = sanitize(state.get("inputs", {}))
    if operation == "retrieval":
        span.set_attribute("gen_ai.data_source.id", state["data_source"])
        span.set_attribute("gen_ai.retrieval.query.text", inputs["query"])
    if operation == "tool":
        span.set_attribute("gen_ai.tool.name", state["tool_name"])
        span.set_attribute("gen_ai.tool.type", "function")
        _set_json(span, "gen_ai.tool.call.arguments", inputs)
        _message(span, "gen_ai.input.messages", inputs,
                 part=lambda x: {"type": "tool_call", "name": state["tool_name"], "arguments": x})
    else:
        _message(span, "gen_ai.input.messages", inputs)
    if finished and state.get("result_available") is True:
        result = sanitize(state["result"])
        if operation == "retrieval":
            _set_json(span, "gen_ai.retrieval.documents", [{"content": v} for v in result])
        if operation == "tool":
            _set_json(span, "gen_ai.tool.call.result", result)
            _message(span, "gen_ai.output.messages", result, output=True, role="tool",
                     part=lambda x: {"type": "tool_call_response", "response": x})
        else:
            _message(span, "gen_ai.output.messages", result, output=True)


def resolve_profile(path, endpoint):
    """Resolve names/IDs through the standard HTTP API; persist before SDK startup."""
    profile = json.loads(Path(path).read_text())
    target = profile["target"]
    api = StudioAPI(profile["resource_api_origin"])
    try:
        result = resolve_resources(StudioProjects(api), StudioAgentStreams(api), **target)
        binding = native_trace_binding(result)
    except ResolutionError as error:
        result, binding = error.evidence, None
    except Exception:
        result, binding = {"status": "failed", "error": "resource_resolution_failed"}, None
    # Retain unrelated settings and known valid routes across temporary API failures.
    if binding is not None:
        profile["binding"] = binding
    profile["resolution"] = result
    profile["effective_trace_endpoint"] = endpoint.rstrip("/") + "/v1/traces"
    Path(path).write_text(json.dumps(profile, indent=2) + "\n")
    return profile


def _validated_binding(profile):
    binding = profile.get("binding")
    if binding is None:
        return None
    fields = binding["resource_attributes"]
    project, stream = fields["splunk_ao.project.id"], fields["splunk_ao.logstream.id"]
    for value in (project, stream):
        if str(UUID(value)) != value:
            raise ValueError("invalid_binding")
    if binding["headers"] != {"projectid": project, "logstreamid": stream}:
        raise ValueError("inconsistent_binding")
    return binding


def configure(app):
    """Use only application-owned slots/hooks; app.shutdown owns the new pipeline."""
    if app.mode != "logs" or getattr(app, "_operation_instrumentation", None) is not None:
        return
    profile_path = os.environ.get("AGENT_PROFILE")
    profile = resolve_profile(profile_path, app.endpoint) if profile_path else {}
    binding = _validated_binding(profile)
    contract = profile.get("target_contract", "studio")
    if contract not in {"studio", "public"}:
        raise ValueError("invalid_target_contract")
    def bind(current):
        selected = _validated_binding(current)
        if selected:
            headers = dict(selected["headers"])
            if contract == "public":
                headers["agentstreamid"] = headers.pop("logstreamid")
            app.trace_session.headers.update(headers)
        return selected

    bind(profile)

    class RoutedExporter(OTLPSpanExporter):
        """Keep one native exporter and augment only its trace Resource view."""
        def export(self, spans):
            selected = _validated_binding(profile)
            if selected:
                spans = [ReadableSpan(
                    name=span.name, context=span.context, parent=span.parent,
                    resource=span.resource.merge(Resource(selected["resource_attributes"])),
                    attributes=span.attributes, events=span.events, links=span.links,
                    kind=span.kind, status=span.status,
                    start_time=span.start_time, end_time=span.end_time,
                    instrumentation_scope=span.instrumentation_scope,
                ) for span in spans]
            return super().export(spans)
    if app.trace_provider is None:
        attrs = dict(RESOURCE.attributes)
        if binding:
            attrs.update(binding["resource_attributes"])
        provider = TracerProvider(resource=Resource(attrs))
        exporter = RoutedExporter(endpoint=f"{app.endpoint}/v1/traces",
                                    session=app.trace_session, timeout=2)
        processor = BatchSpanProcessor(exporter, schedule_delay_millis=3_600_000)
        provider.add_span_processor(processor)
        app.trace_provider = provider
        app.trace_exporter = exporter
        app.trace_processor = processor
    tracer = app.trace_provider.get_tracer("support.operation.instrumentation", "1.0")

    @contextlib.contextmanager
    def operation_hook(name, state):
        if name == "workflow" and profile_path and not profile.get("binding"):
            # A disconnected resource API never disables ordinary traces or logs.
            # Retry at a real application boundary in this same process.
            profile.update(resolve_profile(profile_path, app.endpoint))
            bind(profile)
        if name not in _NAMES:
            yield
            return
        existing = app.trace_producer is not None and name in {"workflow", "model"}
        if existing:
            span = trace.get_current_span()
            _enrich(span, name, state)
            try:
                yield
            except BaseException as error:
                span.set_attribute("error.type", type(error).__name__)
                # Existing producer owns Exception events/status; cancellation is its gap.
                if not isinstance(error, Exception):
                    span.record_exception(error)
                    span.set_status(Status(StatusCode.ERROR))
                raise
            else:
                _enrich(span, name, state, finished=True)
        else:
            with tracer.start_as_current_span(_NAMES[name][0], kind=_NAMES[name][2],
                                             record_exception=False, set_status_on_exception=False) as span:
                _enrich(span, name, state)
                try:
                    yield
                except BaseException as error:
                    span.set_attribute("error.type", type(error).__name__)
                    # Record a sanitized exception without exporting raw message/stack.
                    span.add_event("exception", {"exception.type": type(error).__name__,
                                                "exception.message": "operation failed"})
                    span.set_status(Status(StatusCode.ERROR))
                    raise
                else:
                    _enrich(span, name, state, finished=True)
    if app.trace_producer is not None:
        app.trace_producer.span_hooks.append(lambda span, name, state: _enrich(span, name, state))
    app.operation_hooks.append(operation_hook)
    app._operation_instrumentation = {"tracer": tracer, "profile": profile}

"""Bounded, pre-writer redaction and complete application-owned schema validation."""
import json
import re
from pathlib import Path

from jsonschema import Draft202012Validator, ValidationError

MAX_MESSAGES = 8
MAX_PARTS = 8
MAX_TEXT_BYTES = 1024
MAX_ATTRIBUTE_BYTES = 8192
MAX_DEPTH = 8
MAX_ITEMS = 32
SCHEMAS = json.loads(Path(__file__).with_name("telemetry_schemas.json").read_text())
SENSITIVE = re.compile(
    r"(?i)(?:password|secret|token|authorization|api[_-]?key|email|phone|"
    r"user[_-]?id|tenant[_-]?id|account[_-]?id|session[_-]?id|"
    r"reasoning|chain[_ -]?of[_ -]?thought|private[_-]?prompt)"
)
LABELLED = re.compile(
    r"(?i)\b(password|secret|token|authorization|api[_-]?key|email|phone|"
    r"user[_-]?id|tenant[_-]?id|account[_-]?id|session[_-]?id|"
    r"reasoning|chain[_ -]?of[_ -]?thought)\s*[:=]\s*[^;\n,]+"
)


def bounded(text):
    return text.encode("utf-8")[:MAX_TEXT_BYTES].decode("utf-8", errors="ignore")


def sanitize(value, depth=0):
    if depth >= MAX_DEPTH:
        return "[truncated]"
    if isinstance(value, dict):
        if value.get("type") in ("reasoning", "compaction"):
            value = {**value, "content": "[redacted]"}
        return {bounded(str(k)): "[redacted]" if SENSITIVE.search(str(k)) else sanitize(v, depth + 1)
                for k, v in list(value.items())[:MAX_ITEMS]}
    if isinstance(value, (list, tuple)):
        return [sanitize(v, depth + 1) for v in value[:MAX_ITEMS]]
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except (ValueError, RecursionError):
            parsed = None
        if isinstance(parsed, (dict, list)):
            return bounded(json.dumps(sanitize(parsed, depth + 1), ensure_ascii=False))
        text = LABELLED.sub(lambda m: m.group(1) + "=[redacted]", value)
        text = re.sub(r"(?i)\bBearer\s+\S+", "Bearer [redacted]", text)
        text = re.sub(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}", "[redacted]", text)
        text = re.sub(r"(?i)\b(?:private|secret|sensitive)[_-][A-Za-z0-9_-]+", "[redacted]", text)
        return bounded(text)
    if value is None or isinstance(value, (bool, int, float)):
        return value
    return "[unsupported]"


def is_truncated(value, depth=0):
    if depth >= MAX_DEPTH:
        return True
    if isinstance(value, str):
        return len(value.encode("utf-8")) > MAX_TEXT_BYTES
    if isinstance(value, dict):
        return len(value) > MAX_ITEMS or any(is_truncated(v, depth + 1) for v in value.values())
    if isinstance(value, (list, tuple)):
        return len(value) > MAX_ITEMS or any(is_truncated(v, depth + 1) for v in value)
    return False


def encode(value):
    encoded = json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    if len(encoded.encode("utf-8")) > MAX_ATTRIBUTE_BYTES:
        raise ValueError("capture_byte_limit")
    return encoded


def validate_messages(value, output=False):
    schema = SCHEMAS["model/gen-ai/gen-ai-" + ("output" if output else "input") + "-messages.json"]
    Draft202012Validator(schema).validate(value)
    if len(value) > MAX_MESSAGES:
        raise ValueError("message_limit")
    # GenericPart's permissive anyOf must never mask an invalid concrete part.
    concrete = {part["properties"]["type"]["const"]: name
                for name, part in schema["$defs"].items()
                if "const" in part.get("properties", {}).get("type", {})}
    for message in value:
        if len(message["parts"]) > MAX_PARTS:
            raise ValueError("part_limit")
        for part in message["parts"]:
            if part["type"] in concrete:
                Draft202012Validator({"$defs": schema["$defs"], "$ref": "#/$defs/" + concrete[part["type"]]}).validate(part)
    encode(value)
    return value


def messages(value, *, output=False, tool=False, name=None):
    safe = sanitize(value)
    if isinstance(value, list) and value and all(isinstance(m, dict) and "role" in m for m in value):
        # Preserve typed parts and their order; validate concrete schemas before
        # truncation so malformed known parts cannot become generic text.
        validate_messages(value, output)
        return encode(validate_messages(safe, output))
    if tool:
        part = ({"type": "tool_call_response", "response": safe} if output else
                {"type": "tool_call", "name": name, "arguments": safe})
        role = "tool" if output else "assistant"
    else:
        part = {"type": "text", "content": safe if isinstance(safe, str) else encode(safe)}
        role = "assistant" if output else "user"
    return encode(validate_messages([{"role": role, "parts": [part]}], output))

"""Pre-capture sanitization and complete validation using application-owned schemas."""
import json
import re
from pathlib import Path
from jsonschema import Draft202012Validator

MAX_MESSAGES = 16
MAX_PARTS = 64
MAX_BYTES = 8192
SCHEMAS = json.loads(Path(__file__).with_name("genai_schemas.json").read_text())
SENSITIVE = re.compile(r"(?i)(password|secret|token|authorization|api[_-]?key|email|(?:user|tenant|session|account|conversation|request)[_-]?id|phone|ssn|reasoning|chain[_ -]?of[_ -]?thought|private)")
LABELLED = re.compile(r"""(?i)\b(password|secret|token|authorization|api[_-]?key|email|(?:user|tenant|session|account|conversation|request)[_-]?id|phone|ssn|reasoning|chain[_ -]?of[_ -]?thought)\s*[:=]\s*(?:"[^"]*"|'[^']*'|[^,;\n]+)""")
EMAIL = re.compile(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}")
CREDENTIAL = re.compile(r"(?i)\b(?:bearer\s+\S+|sk-[A-Za-z0-9_-]+|private-[A-Za-z0-9_-]+)")


def sanitize(value, depth=0):
    if depth > 12:
        return "[depth limited]"
    if isinstance(value, dict):
        return {str(k)[:128]: "[redacted]" if SENSITIVE.search(str(k)) else sanitize(v, depth+1)
                for k, v in list(value.items())[:64]}
    if isinstance(value, (list, tuple)):
        return [sanitize(v, depth+1) for v in value[:64]]
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except (ValueError, TypeError):
            parsed = None
        if isinstance(parsed, (dict, list)):
            return json.dumps(sanitize(parsed, depth+1), ensure_ascii=False)
        value = EMAIL.sub("[redacted]", value)
        value = LABELLED.sub(lambda m: m.group(1)+": [redacted]", value)
        value = CREDENTIAL.sub("[redacted]", value)
        return value.encode("utf-8")[:2048].decode("utf-8", "ignore")
    if value is None or isinstance(value, (bool, int, float)):
        return value
    return "[unsupported]"


def was_truncated(value, depth=0):
    if depth > 12:
        return True
    if isinstance(value, str):
        return len(value.encode("utf-8")) > 2048
    if isinstance(value, dict):
        return len(value) > 64 or any(was_truncated(v, depth+1) for v in value.values())
    if isinstance(value, (list, tuple)):
        return len(value) > 64 or any(was_truncated(v, depth+1) for v in value)
    return False


def validate_messages(value, output=False):
    schema = SCHEMAS["model/gen-ai/gen-ai-"+("output" if output else "input")+"-messages.json"]
    Draft202012Validator(schema).validate(value)
    if len(value) > MAX_MESSAGES:
        raise ValueError("message limit")
    # GenericPart allows extension; known types must ALSO pass their concrete schema.
    by_type = {d["properties"]["type"]["const"]: name for name, d in schema["$defs"].items()
               if "const" in d.get("properties", {}).get("type", {})}
    for message in value:
        if len(message["parts"]) > MAX_PARTS:
            raise ValueError("part limit")
        for part in message["parts"]:
            name = by_type.get(part["type"])
            if name:
                Draft202012Validator({"$defs": schema["$defs"], "$ref": "#/$defs/"+name}).validate(part)
    encoded = json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    if len(encoded.encode("utf-8")) > MAX_BYTES:
        raise ValueError("attribute byte limit")
    return encoded


def encode(value):
    encoded = json.dumps(sanitize(value), ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    if len(encoded.encode("utf-8")) > MAX_BYTES:
        raise ValueError("attribute byte limit")
    return encoded


def tool_field(value, result=False):
    safe = sanitize(value)
    schema = SCHEMAS["model/gen-ai/gen-ai-tool-call-"+("result" if result else "arguments")+".json"]
    Draft202012Validator(schema).validate(safe)
    return encode(safe)


def messages(value, output=False, tool=None):
    safe = sanitize(value)
    # Preserve source-owned typed messages, including structured tool parts.
    if not tool:
        if isinstance(safe, dict) and "role" in safe and "parts" in safe:
            return validate_messages([safe], output)
        if isinstance(safe, list) and safe and all(
                isinstance(v, dict) and "role" in v and "parts" in v for v in safe):
            return validate_messages(safe[:MAX_MESSAGES], output)
    if tool:
        part = ({"type": "tool_call_response", "response": safe} if output else
                {"type": "tool_call", "name": tool, "arguments": safe})
        role = "tool" if output else "assistant"
    else:
        part = {"type": "text", "content": safe if isinstance(safe, str) else
                json.dumps(safe, ensure_ascii=False, separators=(",", ":"))}
        role = "assistant" if output else "user"
    return validate_messages([{"role": role, "parts": [part]}], output)
